INSERT INTO _migration_587_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_cells_b003_002', 'topic_wassce_intsci_cells', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following organisms is made up of only one cell?', 'multiple_choice', NULL, '["A. Hydra","B. Earthworm","C. Amoeba","D. Spirogyra"]', 'C', 'Amoeba is a unicellular organism that carries out all life processes within a single cell. Hydra, the earthworm and Spirogyra are multicellular organisms made of many specialised cells. Therefore the correct answer is C: Amoeba.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_cells_b003_003', 'topic_wassce_intsci_cells', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following correctly distinguishes a plant cell from an animal cell?', 'multiple_choice', NULL, '["A. The animal cell has a cell wall; the plant cell does not","B. The plant cell has no nucleus; the animal cell has one","C. Both cells contain chloroplasts for making food","D. The plant cell has a cellulose cell wall and chloroplasts; the animal cell has neither"]', 'D', 'Plant cells are surrounded by a cellulose cell wall and contain chloroplasts with chlorophyll for photosynthesis; animal cells lack both. All plant and animal cells have a nucleus, and only plant cells can photosynthesise. Therefore the correct answer is D: The plant cell has a cellulose cell wall and chloroplasts; the animal cell has neither.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Distinguish', 'AO3', NULL, NULL, NULL),
('q_wisc_cells_b003_004', 'topic_wassce_intsci_cells', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A plant cell placed in a concentrated salt solution loses water. The process by which the water leaves the cell is', 'multiple_choice', NULL, '["A. osmosis","B. active transport","C. transpiration","D. imbibition"]', 'A', 'Water moves from the dilute cell sap through the partially permeable membrane into the concentrated external solution by osmosis, so the cell shrinks (plasmolysis). Active transport moves substances against a gradient using energy, transpiration is water loss from leaves, and imbibition is water uptake by dry materials. Therefore the correct answer is A: osmosis.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO3', NULL, NULL, NULL),
('q_wisc_cells_b003_005', 'topic_wassce_intsci_cells', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A microscope has an eyepiece lens of magnification ×10 and an objective lens of magnification ×40. Calculate the total magnification of the microscope.', 'calculation', NULL, NULL, '×400', 'Total magnification = eyepiece magnification × objective magnification = 10 × 40 = 400. Answer: the total magnification of the microscope is ×400.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_cells_b003_006', 'topic_wassce_intsci_cells', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A student observes plant cells and animal cells under a light microscope.', 'structured', NULL, NULL, '(a) Any two of: plant cells have a cellulose cell wall, animal cells do not; plant cells contain chloroplasts, animal cells do not; plant cells have a large central vacuole, animal cells have small temporary vacuoles; plant cells have a regular shape, animal cells are irregular. (b) Any two of: nucleus — controls the activities of the cell and carries the genetic material; mitochondrion — releases energy from food during respiration; cell membrane — controls the movement of substances into and out of the cell; cytoplasm — site of most chemical reactions of the cell.', '(a) Any two of: plant cells have a cellulose cell wall, animal cells do not; plant cells contain chloroplasts, animal cells do not; plant cells have a large central vacuole, animal cells have small temporary vacuoles; plant cells have a regular shape, animal cells are irregular. (b) Any two of: nucleus — controls the activities of the cell and carries the genetic material; mitochondrion — releases energy from food during respiration; cell membrane — controls the movement of substances into and out of the cell; cytoplasm — site of most chemical reactions of the cell.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_body_b003_001', 'topic_wassce_intsci_body', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Oxygenated blood returns from the lungs to the left atrium of the heart through the', 'multiple_choice', NULL, '["A. Pulmonary artery","B. Pulmonary vein","C. Vena cava","D. Aorta"]', 'B', 'The pulmonary vein returns oxygenated blood from the lungs to the left atrium of the heart. The pulmonary artery carries deoxygenated blood from the heart to the lungs, the vena cava brings deoxygenated blood from the body to the heart, and the aorta distributes oxygenated blood from the heart to the body. Therefore the correct answer is B: Pulmonary vein.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO3', NULL, NULL, NULL);
INSERT INTO _migration_587_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_cells_b003_006_a', 'q_wisc_cells_b003_006', 'a', 'State two differences between the plant cells and the animal cells the student observes.', '2', 'Any two of: plant cells have a cellulose cell wall, animal cells do not; plant cells contain chloroplasts, animal cells do not; plant cells have a large central vacuole, animal cells have small temporary vacuoles; plant cells have a regular shape, animal cells are irregular.', '1'),
('sqp_q_wisc_cells_b003_006_b', 'q_wisc_cells_b003_006', 'b', 'Name two organelles found in both types of cell and state the function of each.', '4', 'Any two of: nucleus — controls the activities of the cell and carries the genetic material; mitochondrion — releases energy from food during respiration; cell membrane — controls the movement of substances into and out of the cell; cytoplasm — site of most chemical reactions of the cell.', '2');
INSERT INTO _migration_587_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_587_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_587_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_587_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_587_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_587_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_587_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_587_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_587_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_587_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_587_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_587_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 2 THEN 1 ELSE 0 END;
